// If payload received via webhook, use it; otherwise fallback to seedChunks
const inputData = ($json.body && Array.isArray($json.body.documents)) ? $json.body.documents : seedChunks;

return inputData.map((doc, idx) => ({
  json: {
    pageContent: `Title: ${doc.title}\nCategory: ${doc.category}\n\n${doc.content}`,
    metadata: {
      doc_id: `doc_${idx + 1}`,
      title: doc.title,
      category: doc.category,
      tags: doc.tags ? doc.tags.join(',') : '',
      source: 'zenthra_internal_kb'
    }
  }
}));

return {
  json: {
    status: 'SUCCESS',
    message: 'Knowledge base documents successfully embedded and synchronized to Supabase pgvector table: zenthra_knowledge',
    total_records: $items().length,
    timestamp: new Date().toISOString()
  }
};
